with src as (select * from shipments where status in ('IN_TRANSIT', 'LOST') and order_id is not null), StatusSummary as (select status, concat_ws(', ', sort_array(collect_set(carrier))) carrier_values, round((100 * sum(case when carrier = 'Kerry' then 1 else 0 end)) / count(*), 1) pct_kerry from src group by status) select status, carrier_values, pct_kerry from StatusSummary where pct_kerry < 36
